<?php
require 'common.php'; adminGuard();
$donors = (int)$pdo->query('SELECT COUNT(*) FROM donors')->fetchColumn();
$appointments = (int)$pdo->query('SELECT COUNT(*) FROM appointments')->fetchColumn();
$pending = (int)$pdo->query("SELECT COUNT(*) FROM appointments WHERE status = 'Pending'")->fetchColumn();
$centres = (int)$pdo->query('SELECT COUNT(*) FROM centres')->fetchColumn();
$recent = $pdo->query('SELECT a.id, a.appointment_date, a.appointment_time, a.status, d.full_name, c.name AS centre_name FROM appointments a JOIN donors d ON d.id=a.donor_id JOIN centres c ON c.id=a.centre_id ORDER BY a.created_at DESC, a.id DESC LIMIT 8')->fetchAll();
?>
